/** Conformance against vectors generated by Bren2010/katie and published by OR13/kt */
import { bytesToHex, hexToBytes } from "@noble/curves/utils.js";
import { describe, expect, test } from "vitest";
import { type Context, rightmostDistinguished, updateView } from "../src/combined.ts";
import { commitment, encodeConfiguration, logLeaf, treeHeadVerifier, vrfInput } from "../src/crypto.ts";
import { frontier, hasLeft, hasRight, left, right, root } from "../src/ibst.ts";
import { baseLadder, monitoringLadder, searchLadder } from "../src/ladder.ts";
import { appendLeaf, computeRoot, fullSubtrees, rootFromFullSubtrees } from "../src/logtree.ts";
import { type Node, evaluate, insert, prove, rootHash } from "../src/prefix.ts";
import localRequests from "./vectors/tsanparency/requests.json" with { type: "json" };
import { decodeUpdateRequest, encodeUpdateRequest } from "../src/messages.ts";
import { KT_128_SHA256_Ed25519, KT_128_SHA256_P256 } from "../src/index.ts";
import { decode, Writer } from "../src/tls.ts";
import v_vrf_p256 from "./vectors/or13/vrf-p256.json" with { type: "json" };
import v_vrf from "./vectors/or13/vrf.json" with { type: "json" };
import v_tree_head from "./vectors/or13/tree-head.json" with { type: "json" };
import v_commitment from "./vectors/or13/commitment.json" with { type: "json" };
import v_binary_ladder from "./vectors/or13/binary-ladder.json" with { type: "json" };
import v_ibst from "./vectors/or13/ibst.json" with { type: "json" };
import v_update_view from "./vectors/or13/update-view.json" with { type: "json" };
import v_log_tree from "./vectors/or13/log-tree.json" with { type: "json" };
import katieAppend from "./vectors/or13/log-append.json" with { type: "json" };
import localAppend from "./vectors/tsanparency/log-append.json" with { type: "json" };
import v_prefix_tree from "./vectors/or13/prefix-tree.json" with { type: "json" };
import v_distinguished from "./vectors/or13/distinguished.json" with { type: "json" };
import v_tree_head_p256 from "./vectors/or13/tree-head-p256.json" with { type: "json" };

// oxlint-disable-next-line typescript/no-explicit-any
type Case = { name: string; input: any; expect: any };
const files: Record<string, { cases: Case[] }> = {
  "vrf-p256": v_vrf_p256,
  vrf: v_vrf,
  "tree-head": v_tree_head,
  commitment: v_commitment,
  "binary-ladder": v_binary_ladder,
  ibst: v_ibst,
  "update-view": v_update_view,
  "log-tree": v_log_tree,
  "prefix-tree": v_prefix_tree,
  distinguished: v_distinguished,
  "tree-head-p256": v_tree_head_p256,
};
const cases = (file: string): Case[] => files[file]!.cases;
const hex = (s: string) => hexToBytes(s);

const vrfs = [
  ["KT_128_SHA256_P256", "vrf-p256", KT_128_SHA256_P256.vrf],
  ["KT_128_SHA256_Ed25519", "vrf", KT_128_SHA256_Ed25519.vrf],
] as const;

describe.each(vrfs)("VRF with %s (Section 11.7)", (_, file, vrf) => {
  test.each(cases(file))("$name", ({ input, expect: want }) => {
    const key = vrf.key(hex(input.private_key));
    expect(bytesToHex(key.publicKey)).toBe(input.public_key);
    const alpha = vrfInput(hex(input.label), input.version);
    const verify = vrf.verifier(key.publicKey);
    if (want.error) return expect(verify(alpha, hex(input.proof))).toBeNull();
    expect(bytesToHex(alpha)).toBe(want.vrf_input);
    const { proof, output } = key.prove(alpha);
    expect(bytesToHex(proof)).toBe(want.proof);
    expect(bytesToHex(output)).toBe(want.output);
    expect(bytesToHex(verify(alpha, proof)!)).toBe(want.output);
  });
});

describe("commitment (Section 11.6)", () => {
  test.each(cases("commitment"))("$name", ({ input, expect: want }) => {
    const c = bytesToHex(commitment(hex(input.opening), hex(input.label), input.version, hex(input.update.value)));
    if (want.error) expect(c).not.toBe(input.commitment);
    else expect(c).toBe(want.commitment);
  });
});

describe("binary ladder (Section 5, Appendix B)", () => {
  test.each(cases("binary-ladder"))("$name", ({ input, expect: want }) => {
    if (input.kind === "base") return expect(baseLadder(input.greatest)).toEqual(want.versions);
    if (input.kind === "monitoring") return expect(monitoringLadder(input.target)).toEqual(want.versions);
    const seen: number[] = [];
    searchLadder(input.target, (v) => {
      if (!input.left_inclusion.includes(v) && !input.right_non_inclusion.includes(v)) seen.push(v);
      return v <= input.greatest;
    });
    expect(seen).toEqual(want.versions);
  });
});

describe("implicit binary search tree (Section 4.1, Appendix A)", () => {
  // uint64 values above 2^53 - 1 are rejected by design
  test.each(cases("ibst").filter((c) => Number.isSafeInteger(c.input.size)))(
    "$name",
    ({ input: { size }, expect: want }) => {
      expect(root(size)).toBe(want.root);
      expect(frontier(size)).toEqual(want.frontier);
      for (const n of want.nodes) {
        expect(hasLeft(n.index) ? left(n.index) : null).toBe(n.left);
        expect(hasRight(n.index, size) ? right(n.index, size) : null).toBe(n.right);
      }
    },
  );
});

/** A context that records which timestamps an algorithm asks for. */
function recorder(n: number, timestamps: (x: number) => number = () => 0) {
  const asked: number[] = [];
  const seen = new Set<number>();
  const ctx: Context = {
    n,
    timestamp: (x) => {
      if (!seen.has(x)) {
        seen.add(x);
        asked.push(x);
      }
      return timestamps(x);
    },
    ladder: () => {},
  };
  return { ctx, asked };
}

describe("updating the view (Section 4.2)", () => {
  test.each(cases("update-view"))("$name", ({ input, expect: want }) => {
    const { ctx, asked } = recorder(input.size);
    updateView(ctx, input.advertised ?? 0);
    expect(asked).toEqual(want.entries);
  });
});

describe("distinguished log entries (Section 6.1)", () => {
  test.each(cases("distinguished").filter((c) => c.input.size > 0))("$name", ({ input, expect: want }) => {
    const { ctx } = recorder(input.size, (x) => input.timestamps[x]);
    expect(rightmostDistinguished(ctx, input.window)).toBe(want.rightmost ?? undefined);
  });
});

describe("log tree (Sections 3.2, 11.8, 12.1)", () => {
  test.each(cases("log-tree"))("$name", ({ input, expect: want }) => {
    const n = input.entries.length;
    const leaves = input.entries.map((e: { timestamp: number; prefix_tree: string }) =>
      logLeaf(e.timestamp, hex(e.prefix_tree)),
    );
    expect(leaves.map(bytesToHex)).toEqual(want.leaf_values);
    const all = new Map<string, Uint8Array>();
    const head = (start: number, size: number): Uint8Array => {
      const k = `${start}:${size}`;
      if (!all.has(k)) {
        const proved = computeRoot(
          size,
          new Map(leaves.slice(start, start + size).map((l: Uint8Array, i: number) => [i, l])),
          undefined,
          () => {
            throw new Error("unreachable");
          },
        );
        all.set(k, proved.root);
      }
      return all.get(k)!;
    };
    const full = fullSubtrees(n).map((r) => head(r.start, r.size));
    expect(full.map(bytesToHex)).toEqual(want.full_subtrees);

    for (const [i, req] of input.requests.entries()) {
      const known = new Map<number, Uint8Array>(req.proven_leaves.map((x: number) => [x, leaves[x]]));
      const m = req.retained_size ?? 0;
      const retained = m ? { size: m, heads: fullSubtrees(m).map((r) => head(r.start, r.size)) } : undefined;
      const elements: Uint8Array[] = [];
      const proved = computeRoot(n, known, retained, (r) => {
        const h = head(r.start, r.size);
        elements.push(h);
        return h;
      });
      expect(bytesToHex(proved.root)).toBe(want.root);
      const w = new Writer().count(2, elements.length);
      for (const e of elements) w.bytes(e);
      expect(bytesToHex(w.finish())).toBe(want.proofs[i].proof);
    }
  });
});

describe("prefix tree (Sections 3.3, 11.9, 12.2)", () => {
  test.each(cases("prefix-tree"))("$name", ({ input, expect: want }) => {
    let tree: Node = null;
    for (const e of input.entries) tree = insert(tree, hex(e.vrf_output), hex(e.commitment));
    expect(bytesToHex(rootHash(tree))).toBe(want.root);
    const keys = input.searches.map(hex);
    const proof = prove(tree, keys);
    expect(proof.results.map((r) => ({ result_type: r.type, depth: r.depth }))).toEqual(
      want.results.map((r: { result_type: number; depth: number }) => ({ result_type: r.result_type, depth: r.depth })),
    );
    expect(proof.elements.map(bytesToHex)).toEqual(want.elements);
    const lookups = keys.map((key: Uint8Array, i: number) => ({
      key,
      result: proof.results[i]!,
      commitment: want.commitments[i] ? hex(want.commitments[i]) : undefined,
    }));
    expect(bytesToHex(evaluate(lookups, proof.elements))).toBe(want.root);
  });
});

const heads = [
  ["KT_128_SHA256_P256", "tree-head-p256", KT_128_SHA256_P256],
  ["KT_128_SHA256_Ed25519", "tree-head", KT_128_SHA256_Ed25519],
] as const;

describe.each(heads)("tree head with %s (Sections 11.2, 11.4)", (_, file, cipherSuite) => {
  test.each(cases(file).filter((c) => c.input.mode === 1))("$name", async ({ input, expect: want }) => {
    const config = {
      cipherSuite,
      signaturePublicKey: hex(input.signature_public_key),
      vrfPublicKey: hex(input.vrf_public_key),
      maxAhead: input.max_ahead,
      maxBehind: input.max_behind,
      reasonableMonitoringWindow: input.reasonable_monitoring_window,
    };
    expect(bytesToHex(encodeConfiguration(config))).toBe(want.configuration);
    const verify = await treeHeadVerifier(config);
    expect(await verify(input.tree_size, hex(input.root), hex(want.signature))).toBe(true);
    expect(await verify(input.tree_size + 1, hex(input.root), hex(want.signature))).toBe(false);
  });
});

for (const [source, vectors] of [
  ["katie", katieAppend],
  ["tsanparency", localAppend],
] as const) {
  test(`${source} log append sequence`, () => {
    let heads: Uint8Array[] = [];
    const leaves: string[] = [];
    for (const { input, expect: expected } of vectors.cases) {
      const [entry] = input.entries;
      const leaf = logLeaf(entry!.timestamp, hex(entry!.prefix_tree));
      heads = appendLeaf(leaves.length, heads, leaf);
      leaves.push(bytesToHex(leaf));
      expect(input.size).toBe(leaves.length);
      expect(leaves).toEqual(input.leaves);
      expect(heads.map(bytesToHex)).toEqual(expected.full_subtrees);
      expect(bytesToHex(rootFromFullSubtrees(input.size, heads))).toBe(expected.root);
    }
  });
}

test.each(localRequests.cases)("update request $name", ({ input, expect: expected }) => {
  const request = { label: hex(input.label), last: input.last, values: input.values.map(hex) };
  expect(bytesToHex(encodeUpdateRequest(request))).toBe(expected.encoding);
  expect(decode(hex(expected.encoding), decodeUpdateRequest)).toEqual(request);
});
